import arrtForm from "./components/extemal/arrtForm";
import { getExtCodeList, globalattrSearch, globalattrDel } from "@/api/system/extemal";
export default {
  components: {
    arrtForm: arrtForm
  },
  data: function data() {
    return {
      selectionList: [],
      cmdbCiIdList: [],
      cmdbAttrCodeList: [],
      i6000AttrCodeList: [],
      searchForm: {
        current: 1,
        size: 20,
        extCode: undefined,
        extId: undefined,
        extName: undefined,
        extPid: undefined
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: '',
      extCodeList: null
    };
  },
  mounted: function mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getDict();
    this.getList();
  },
  methods: {
    selectionChange: function selectionChange(selection) {
      //点击选择事件
      this.selectionList = selection.map(function (item) {
        return item.id;
      });
    },
    changeStatus: function changeStatus(row) {
      if (row.i6000OriType === '1') {
        return "手工录入";
      } else if (row.i6000OriType === '2') {
        return "枚举数据";
      } else if (row.i6000OriType === '3') {
        return "配置类型";
      } else if (row.i6000OriType === '4') {
        return "外部数据";
      }
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        var items = dictList.filter(function (item) {
          return item.dictKey == code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    handleReset: function handleReset() {
      this.searchForm.extCode = undefined;
      this.searchForm.extId = undefined;
      this.searchForm.extName = undefined;
      this.searchForm.extPid = undefined;
      this.getList();
    },
    getDict: function getDict() {
      var _this = this;
      getExtCodeList().then(function (res) {
        _this.extCodeList = res.data;
      });
    },
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight - 120 + 'px';
    },
    getList: function getList() {
      var _this2 = this;
      this.tableLoading = true;
      globalattrSearch(this.searchForm).then(function (res) {
        _this2.tableData = res.data.records;
        _this2.total = res.data.total;
        _this2.tableLoading = false;
      }).catch(function () {
        _this2.tableLoading = false;
      });
    },
    // 删除
    delArrt: function delArrt() {
      var _this3 = this;
      this.$confirm('确定是否删除?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        globalattrDel({
          ids: _this3.selectionList.join(',')
        }).then(function (res) {
          _this3.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this3.getList();
        });
      });
    },
    // 编辑
    editArrt: function editArrt(row) {
      this.showType = '修改';
      this.arrtId = row.id;
      this.showForm = true;
    },
    saveGlobalArrt: function saveGlobalArrt() {
      this.showForm = false;
      this.getList();
    }
  }
};
